CREATE TABLE entities (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, plugin_manifest_id bigint NOT NULL, plugin_code text NOT NULL, source_record_id bigint NOT NULL, source_id bigint NOT NULL, external_id text NOT NULL, name text NOT NULL, city text, address text, lng double precision, lat double precision, geom geometry(Point,4326) GENERATED ALWAYS AS (CASE WHEN lng IS NOT NULL AND lat IS NOT NULL THEN ST_SetSRID(ST_MakePoint(lng,lat),4326) END) STORED, attributes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(plugin_manifest_id,plugin_code) REFERENCES plugin_manifests(id,code) ON DELETE RESTRICT, FOREIGN KEY(source_record_id,source_id) REFERENCES source_records(id,source_id) ON DELETE RESTRICT, CHECK(external_id<>'' AND name<>''), CHECK(jsonb_typeof(attributes)='object'), CHECK((lng IS NULL)=(lat IS NULL)), CHECK(lng IS NULL OR (lng = lng AND lng BETWEEN -180 AND 180)), CHECK(lat IS NULL OR (lat = lat AND lat BETWEEN -90 AND 90)), UNIQUE(plugin_manifest_id,source_id,external_id), UNIQUE(id,plugin_manifest_id));
CREATE INDEX entities_geom_gist ON entities USING gist(geom); CREATE INDEX entities_name_trgm ON entities USING gin(name gin_trgm_ops); CREATE INDEX entities_plugin_manifest_id_idx ON entities(plugin_manifest_id);
CREATE TABLE items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, entity_id bigint NOT NULL, plugin_manifest_id bigint NOT NULL, source_record_id bigint NOT NULL, source_id bigint NOT NULL, external_id text NOT NULL, title text NOT NULL, attributes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(entity_id,plugin_manifest_id) REFERENCES entities(id,plugin_manifest_id) ON DELETE CASCADE, FOREIGN KEY(source_record_id,source_id) REFERENCES source_records(id,source_id) ON DELETE RESTRICT, CHECK(external_id<>'' AND title<>''), CHECK(jsonb_typeof(attributes)='object'), UNIQUE(plugin_manifest_id,source_id,external_id));
CREATE INDEX items_entity_id_idx ON items(entity_id); CREATE INDEX items_title_trgm ON items USING gin(title gin_trgm_ops);
